import itertools


def energia(qubo, x):
    return sum(c * __import__("math").prod(x[i] for i in indices) for indices, c in qubo.items())


def elegir_cartera(penalizacion):
    penalizacion = 0.01
    rendimiento = (0.10, 0.08, 0.06, 0.04)
    riesgo = (0.10, 0.08, 0.05, 0.02)
    qubo = {(): penalizacion * 4}
    for i in range(4):
        qubo[(i,)] = -rendimiento[i] + 0.3 * riesgo[i] - 3 * penalizacion
        for j in range(i + 1, 4):
            qubo[(i, j)] = 2 * penalizacion
    return min(itertools.product([0, 1], repeat=4), key=lambda x: energia(qubo, x))

from qiskit import QuantumCircuit
from qiskit.transpiler import generate_preset_pass_manager
from qiskit_ibm_runtime.executor_sampler import Sampler
from qiskit_ibm_runtime.fake_provider import FakeManilaV2


def trotter(n, J, h, dt, pasos):
    qc = QuantumCircuit(n)
    for _ in range(pasos):
        for i in range(n - 1):
            qc.rzz(2 * J * dt, i, i + 1)
        for i in range(n):
            qc.rx(2 * h * dt, i)
    return qc


def magnetizacion(conteos, n):
    return 0.0  # ✏️ cada bit 0 vale +1 y cada 1 vale -1; promedia sobre los n bits y los disparos


def magnetizacion_conteos(n, J, h, dt, pasos, disparos):
    backend = FakeManilaV2()
    qc = trotter(n, J, h, dt, pasos)
    qc.measure_all()
    isa = generate_preset_pass_manager(1, backend=backend, seed_transpiler=1).run(qc)
    sampler = Sampler(mode=backend)
    sampler.options.simulator.seed_simulator = 3
    conteos = sampler.run([isa], shots=disparos).result()[0].data.meas.get_counts()
    return magnetizacion(conteos, n)
